// Deterministic only: no model call, no cost, no invented text.
// Output is a per-tenant summary list. The actual SEND step (channel + template +
// owner approval) is TBD-F3 — this draft writes the summary to audit only and
// never sends a message by itself, so a draft bug cannot spam owners/customers.
const rows = $input.all().map(i => i.json);
const reminders = rows.map(r => ({ tenant_id: r.tenant_id, open_conversations: Number(r.open_conversations), last_activity: r.last_activity, reminder: 'follow_up_due' }));
return [{ json: { tenants_due: reminders.length, reminders, generated_at: new Date().toISOString() } }];
